// import-prototype.test.mjs — real-import-mvp wt-A (A1/A2 verification).
// Fixtures: resources/Icons34x34byAilsEnglish2013.zip (402 PNG @ 34x34 RGBA,
// reviewed) — I_Chest01.png (large blocks), I_Key01.png (thin lines),
// I_GoldCoin.png (high-transparency edge), committed under fixtures/import/
// with original filenames; each `<base>.compare.png` is generated by
// tools/import-prototype.mjs (source left, quantized right, 98x64).
// Reuses production modules (pngjs decode, quantizeGeometry, OKLCH
// mapFrameToPalette, pixelsToSvg); no network, deterministic.
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { PNG } from 'pngjs';
import { computeFit, quantizeGeometry } from './quantize.mjs';
import { loadPalette, getMappableColors, mapFrameToPalette } from './palette.mjs';
import {
  decodePngFile,
  quantizeAndMap,
  buildCompare,
  resolveSlots,
  svgForSlot,
} from './import-prototype.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const FIX = ['I_Chest01.png', 'I_Key01.png', 'I_GoldCoin.png'];
const PNG_SIG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

const potion = JSON.parse(readFileSync(resolve(root, 'assets/potion_001/asset.json'), 'utf8'));
const prop = loadPalette(resolve(root, 'palettes/palette_prop.v1.json'));

function pngDims(buf) {
  assert.deepEqual(buf.subarray(0, 8), PNG_SIG, 'bad PNG signature');
  return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20) };
}

describe('A1 real import pipeline (34px icon -> 64 static slot)', () => {
  // Independent basis (arithmetic, not recorded): scale = 64/max(34,34),
  // dst = round(34*scale) = 64 each side, offsets = floor((64-64)/2) = 0.
  it('34x34 source fits 64 tier exactly (no pad)', () => {
    assert.deepEqual(computeFit(34, 34, 64), { dstW: 64, dstH: 64, offsetX: 0, offsetY: 0 });
  });

  it('mapped output is closed: palette-exact bytes or transparent', async () => {
    const src = await decodePngFile(resolve(root, 'fixtures/import/I_Chest01.png'));
    assert.equal(src.width, 34);
    assert.equal(src.height, 34);
    const { geo, mapped } = quantizeAndMap(src, potion, prop);
    assert.equal(geo.width, 64);
    assert.equal(geo.height, 64);
    const allowed = new Set(getMappableColors(prop).map((c) => `${c.r},${c.g},${c.b}`));
    let opaque = 0;
    for (let i = 0; i < mapped.data.length; i += 4) {
      if (mapped.data[i + 3] === 0) {
        assert.deepEqual([mapped.data[i], mapped.data[i + 1], mapped.data[i + 2]], [0, 0, 0]);
      } else {
        assert.equal(mapped.data[i + 3], 255);
        assert.ok(allowed.has(`${mapped.data[i]},${mapped.data[i + 1]},${mapped.data[i + 2]}`));
        opaque++;
      }
    }
    assert.ok(opaque > 0, 'chest must land opaque pixels (large blocks)');
    assert.deepEqual(mapped.names.length, 64 * 64);
  });

  it('--dir slot resolution (pure, no disk)', () => {
    assert.equal(resolveSlots(potion, null).length, 8);
    assert.deepEqual(resolveSlots(potion, 'fr'), [
      { persp: 'td', dir: 'fr' },
      { persp: 'sd', dir: 'fr' },
    ]);
    assert.deepEqual(resolveSlots(potion, 'td/bk'), [{ persp: 'td', dir: 'bk' }]);
    assert.throws(() => resolveSlots(potion, 'up'), /--dir/);
    assert.throws(() => resolveSlots(potion, 'xx/fr'), /--dir/);
  });

  it('fresh compare canvas follows W=srcW+size, H=max(srcH,size)', async () => {
    const src = await decodePngFile(resolve(root, 'fixtures/import/I_Chest01.png'));
    const { mapped } = quantizeAndMap(src, potion, prop);
    const cmp = buildCompare(src.data, src.width, src.height, mapped.data, potion.size);
    assert.equal(cmp.width, src.width + potion.size);
    assert.equal(cmp.height, Math.max(src.height, potion.size));
    assert.equal(cmp.width, 98);
    assert.equal(cmp.height, 64);
  });

  it('pipeline runs byte-identical twice (svg + compare, no shimmer)', async () => {
    const src = await decodePngFile(resolve(root, 'fixtures/import/I_Key01.png'));
    const run = () => {
      const q = quantizeAndMap(src, potion, prop);
      const clip = potion.actions.idle.clips.td.fr[0];
      const svg = svgForSlot(q, potion, prop, 'td', 'fr', clip, 'I_Key01', false);
      const cmp = buildCompare(src.data, src.width, src.height, q.mapped.data, potion.size);
      return { svg, cmp: Buffer.from(cmp.data) };
    };
    const a = run();
    const b = run();
    assert.equal(a.svg, b.svg);
    assert.ok(a.cmp.equals(b.cmp));
  });

  it('prop keeps dither lock (ordered-bayer still rejected)', () => {
    const frame = new Uint8ClampedArray([122, 199, 79, 255]);
    assert.throws(() => mapFrameToPalette(frame, 1, 1, prop, { dither: 'ordered-bayer' }));
  });
});

describe('A2 fixtures + compare contract (offline)', () => {
  it('3 sources + 3 compares committed with original names', () => {
    for (const f of [...FIX, ...FIX.map((f) => f.replace(/\.png$/i, '.compare.png'))]) {
      assert.ok(existsSync(resolve(root, 'fixtures/import', f)), `fixtures/import/${f} missing`);
    }
  });

  // Formula: W = srcW + size (34+64=98), H = max(srcH, size) (=64).
  // Left panel must equal source bytes, right panel the mapped result.
  for (const f of FIX) {
    it(`${f.replace('.png', '')} compare is 98x64 with src-left/mapped-right panels`, async () => {
      const src = await decodePngFile(resolve(root, 'fixtures/import', f));
      const { mapped } = quantizeAndMap(src, potion, prop);
      const buf = readFileSync(resolve(root, 'fixtures/import', f.replace(/\.png$/i, '.compare.png')));
      assert.deepEqual(pngDims(buf).w, src.width + potion.size);
      assert.deepEqual(pngDims(buf).h, Math.max(src.height, potion.size));
      const cmp = PNG.sync.read(buf);
      assert.equal(cmp.width, 98);
      assert.equal(cmp.height, 64);
      const left = new Uint8ClampedArray(34 * 34 * 4);
      for (let y = 0; y < 34; y++) {
        for (let x = 0; x < 34; x++) {
          const si = (y * 98 + x) * 4;
          const di = (y * 34 + x) * 4;
          left[di] = cmp.data[si];
          left[di + 1] = cmp.data[si + 1];
          left[di + 2] = cmp.data[si + 2];
          left[di + 3] = cmp.data[si + 3];
        }
      }
      assert.deepEqual(left, src.data);
      const right = new Uint8ClampedArray(64 * 64 * 4);
      for (let y = 0; y < 64; y++) {
        for (let x = 0; x < 64; x++) {
          const si = (y * 98 + (34 + x)) * 4;
          const di = (y * 64 + x) * 4;
          right[di] = cmp.data[si];
          right[di + 1] = cmp.data[si + 1];
          right[di + 2] = cmp.data[si + 2];
          right[di + 3] = cmp.data[si + 3];
        }
      }
      assert.deepEqual(right, mapped.data);
    });
  }

  it('landed potion slots validate --check-files shape (8 views present)', async () => {
    const { validateAsset } = await import('./asset-manifest.mjs');
    const r = validateAsset(potion, { checkFiles: true, baseDir: resolve(root, 'assets/potion_001') });
    assert.deepEqual(r.errors, [], r.errors.join('; '));
    assert.equal(r.ok, true);
  });
});
